<#
.SYNOPSIS
    Harbinger's Purge canonical launcher.

.DESCRIPTION
    Main-branch launcher for Windows 11 and Windows Server 2022.
    Shows the Harbinger menu on the left and preserves the exact Grim Reaper
    appearance from the supplied screenshot on the right on GUI-capable systems.

    Option 1 starts the Purge executor.
    Option 2 starts the CyberPatriot Toolkit / Installer GUI.

    The launcher downloads only from the main branch and never references
    another Git branch.

.AUTHOR
    Channveer Singh
#>

[CmdletBinding()]
param(
    [switch]$KeepDownloadedFiles
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

$RepositoryOwner = 'HarbringerGone'
$RepositoryName = 'Harbingers-purge'
$Branch = 'main'
$TempRoot = $null
$script:ReaperBase64 = ''

function Get-OsInfo {
    $os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
    $build = 0
    [void][int]::TryParse([string]$os.BuildNumber, [ref]$build)
    $edition = 'Unknown'
    $install = 'Unknown'

    try {
        $cv = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop
        $edition = [string]$cv.EditionID
        $install = [string]$cv.InstallationType
    } catch {}

    $kind = $null
    if ([int]$os.ProductType -eq 1 -and $build -ge 22000) {
        $kind = 'Windows 11'
    }
    elseif ([int]$os.ProductType -in 2,3 -and $build -eq 20348) {
        $kind = 'Windows Server 2022'
    }

    return [pscustomobject]@{
        Caption = [string]$os.Caption
        Build = $build
        ProductType = [int]$os.ProductType
        Edition = $edition
        InstallationType = $install
        Kind = $kind
    }
}

function Test-SupportedWindows {
    $os = Get-OsInfo
    if (-not $os.Kind) {
        throw "Unsupported OS: $($os.Caption) | edition=$($os.Edition) | install=$($os.InstallationType) | build=$($os.Build). Harbinger's Purge supports Windows 11 and Windows Server 2022."
    }
    return $os
}

function New-RawUrl {
    param([Parameter(Mandatory)][string]$FileName)
    # Build the query parameter separately so PowerShell never interprets
    # ?nocache as part of a variable name.
    $base = 'https://raw.githubusercontent.com/{0}/{1}/refs/heads/{2}/{3}' -f $RepositoryOwner,$RepositoryName,$Branch,$FileName
    $nonce = [guid]::NewGuid().ToString('N')
    return $base + '?nocache=' + $nonce
}

function Write-Status {
    param([Parameter(Mandatory)][string]$Message)
    Write-Host "[Harbinger's Launcher] $Message" -ForegroundColor Cyan
}

function Test-Administrator {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($identity)
    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

function Test-PowerShellSyntax {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$Label
    )
    $tokens = $null
    $errors = $null
    [void][System.Management.Automation.Language.Parser]::ParseFile($Path,[ref]$tokens,[ref]$errors)
    if ($errors -and $errors.Count -gt 0) {
        $messages = @($errors | ForEach-Object { $_.Message }) -join ' | '
        throw "$Label syntax check failed: $messages"
    }
}

function Test-AsciiFile {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$Label
    )
    foreach ($byte in [IO.File]::ReadAllBytes($Path)) {
        if ($byte -gt 127) {
            throw "$Label contains non-ASCII bytes. Publish it as ASCII/Windows PowerShell 5.1 compatible text."
        }
    }
}

function Download-ReleaseFiles {
    param([switch]$IncludeToolkit)

    if (-not $TempRoot) {
        $script:TempRoot = Join-Path $env:TEMP ('HarbingersPurgeLaunch-' + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $TempRoot -Force | Out-Null
    }

    $files = New-Object System.Collections.Generic.List[object]
    $files.Add([pscustomobject]@{Name='Purge Executor';File='Harbingers-Purge.ps1';Destination=(Join-Path $TempRoot 'Harbingers-Purge.ps1')})
    $files.Add([pscustomobject]@{Name='wsd.crt';File='wsd.crt';Destination=(Join-Path $TempRoot 'wsd.crt')})
    if ($IncludeToolkit) {
        $files.Add([pscustomobject]@{Name='GUI Toolkit';File='Harbingers-CyberPatriot-Toolkit.ps1';Destination=(Join-Path $TempRoot 'Harbingers-CyberPatriot-Toolkit.ps1')})
    }

    foreach ($item in $files) {
        $url = New-RawUrl -FileName $item.File
        Write-Status "Downloading $($item.Name) from main..."
        Invoke-WebRequest -Uri $url -OutFile $item.Destination -UseBasicParsing -MaximumRedirection 5
        if (-not (Test-Path -LiteralPath $item.Destination -PathType Leaf)) {
            throw "Download failed: $($item.Name)."
        }
        if ((Get-Item -LiteralPath $item.Destination).Length -le 0) {
            throw "Downloaded file is empty: $($item.Name)."
        }
    }

    $certPath = Join-Path $TempRoot 'wsd.crt'
    $certText = Get-Content -LiteralPath $certPath -Raw
    if (($certText -notmatch '-----BEGIN CERTIFICATE-----') -or ($certText -notmatch '-----END CERTIFICATE-----')) {
        throw 'The downloaded wsd.crt does not look like a PEM certificate.'
    }

    Test-AsciiFile -Path (Join-Path $TempRoot 'Harbingers-Purge.ps1') -Label 'Purge Executor'
    Test-PowerShellSyntax -Path (Join-Path $TempRoot 'Harbingers-Purge.ps1') -Label 'Purge Executor'

    if ($IncludeToolkit) {
        Test-AsciiFile -Path (Join-Path $TempRoot 'Harbingers-CyberPatriot-Toolkit.ps1') -Label 'GUI Toolkit'
        Test-PowerShellSyntax -Path (Join-Path $TempRoot 'Harbingers-CyberPatriot-Toolkit.ps1') -Label 'GUI Toolkit'
    }
}

function Start-Purge {
    Download-ReleaseFiles
    $purgePath = Join-Path $TempRoot 'Harbingers-Purge.ps1'
    Write-Status 'Starting Harbingers-Purge.ps1...'
    return (Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe') -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$purgePath) -PassThru)
}

function Start-Installer {
    Download-ReleaseFiles -IncludeToolkit
    $toolkitPath = Join-Path $TempRoot 'Harbingers-CyberPatriot-Toolkit.ps1'
    $purgePath = Join-Path $TempRoot 'Harbingers-Purge.ps1'
    Write-Status 'Starting Harbingers-CyberPatriot-Toolkit.ps1...'
    return (Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe') -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$toolkitPath,'-PurgeScriptPath',$purgePath,'-InstallerOnly') -PassThru)
}

function Get-ReaperImage {
    $bytes = [Convert]::FromBase64String($script:ReaperBase64)
    $stream = New-Object IO.MemoryStream(,$bytes)
    try {
        $image = [Drawing.Image]::FromStream($stream)
        $bitmap = New-Object Drawing.Bitmap($image)
        $image.Dispose()
        return $bitmap
    } finally {
        $stream.Dispose()
    }
}

# Password gate for the launcher. The plaintext password is intentionally NOT stored in this file.
$script:LauncherPasswordSha256 = '4fa094c23bdd6e55416408075a860709dbf1dc1424ba132beab959b356e6cb14'

function Get-Sha256Hex {
    param([Parameter(Mandatory)][string]$Text)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($Text)
        return ([System.BitConverter]::ToString($sha.ComputeHash($bytes)) -replace '-','').ToLowerInvariant()
    }
    finally { $sha.Dispose() }
}

function Convert-SecureStringToPlainText {
    param([Parameter(Mandatory)][System.Security.SecureString]$SecureText)
    $bstr = [IntPtr]::Zero
    try {
        $bstr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($SecureText)
        return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr)
    }
    finally {
        if ($bstr -ne [IntPtr]::Zero) { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr) }
    }
}

function Test-LauncherPassword {
    param([Parameter(Mandatory)][System.Security.SecureString]$Password)
    $plain = Convert-SecureStringToPlainText -SecureText $Password
    try {
        $actual = Get-Sha256Hex -Text $plain
        return [StringComparer]::OrdinalIgnoreCase.Equals($actual,$script:LauncherPasswordSha256)
    }
    finally { $plain = $null }
}

function Request-LauncherPasswordGui {
    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $dialog = New-Object Windows.Forms.Form
    $dialog.Text = "Harbinger's Purge - Authentication"
    $dialog.FormBorderStyle = [Windows.Forms.FormBorderStyle]::FixedDialog
    $dialog.StartPosition = 'CenterScreen'
    $dialog.ClientSize = New-Object Drawing.Size(430,190)
    $dialog.MaximizeBox = $false
    $dialog.MinimizeBox = $false
    $dialog.BackColor = [Drawing.Color]::Black
    $dialog.ForeColor = [Drawing.Color]::Gainsboro

    $label = New-Object Windows.Forms.Label
    $label.Text = "ENTER HARBINGER'S PURGE PASSWORD"
    $label.Left = 28; $label.Top = 24; $label.Width = 370; $label.Height = 24
    $label.Font = New-Object Drawing.Font('Consolas',10,[Drawing.FontStyle]::Bold)
    $label.ForeColor = [Drawing.Color]::Gainsboro
    $label.BackColor = [Drawing.Color]::Black
    $dialog.Controls.Add($label)

    $box = New-Object Windows.Forms.TextBox
    $box.Left = 28; $box.Top = 58; $box.Width = 370; $box.Height = 30
    $box.UseSystemPasswordChar = $true
    $box.BackColor = [Drawing.Color]::FromArgb(20,20,20)
    $box.ForeColor = [Drawing.Color]::Gainsboro
    $box.BorderStyle = [Windows.Forms.BorderStyle]::FixedSingle
    $dialog.Controls.Add($box)

    $ok = New-Object Windows.Forms.Button
    $ok.Text = 'UNLOCK'
    $ok.Left = 210; $ok.Top = 112; $ok.Width = 90; $ok.Height = 36
    $ok.DialogResult = [Windows.Forms.DialogResult]::OK
    $ok.BackColor = [Drawing.Color]::FromArgb(20,20,20)
    $ok.ForeColor = [Drawing.Color]::Gainsboro
    $ok.FlatStyle = [Windows.Forms.FlatStyle]::Flat
    $dialog.Controls.Add($ok)

    $cancel = New-Object Windows.Forms.Button
    $cancel.Text = 'EXIT'
    $cancel.Left = 308; $cancel.Top = 112; $cancel.Width = 90; $cancel.Height = 36
    $cancel.DialogResult = [Windows.Forms.DialogResult]::Cancel
    $cancel.BackColor = [Drawing.Color]::FromArgb(15,15,15)
    $cancel.ForeColor = [Drawing.Color]::Gray
    $cancel.FlatStyle = [Windows.Forms.FlatStyle]::Flat
    $dialog.Controls.Add($cancel)

    $dialog.AcceptButton = $ok
    $dialog.CancelButton = $cancel
    [void]$box.Focus()

    try {
        for ($attempt = 1; $attempt -le 3; $attempt++) {
            $result = $dialog.ShowDialog()
            if ($result -ne [Windows.Forms.DialogResult]::OK) { return $false }
            $secure = ConvertTo-SecureString -String $box.Text -AsPlainText -Force
            $box.Clear()
            if (Test-LauncherPassword -Password $secure) { return $true }
            if ($attempt -lt 3) {
                [Windows.Forms.MessageBox]::Show(("Access denied. Attempt {0} of 3." -f $attempt),'Harbinger''s Purge',[Windows.Forms.MessageBoxButtons]::OK,[Windows.Forms.MessageBoxIcon]::Error) | Out-Null
                $box.Clear()
                continue
            }

            [Windows.Forms.MessageBox]::Show("running scorchtheearth ,`n`nFinal authorization attempt failed. Harbinger project files will be removed from this folder and Harbinger temporary copies will be cleaned up.",'Harbinger''s Purge',[Windows.Forms.MessageBoxButtons]::OK,[Windows.Forms.MessageBoxIcon]::Stop) | Out-Null
        }
        return $false
    }
    finally { $dialog.Dispose() }
}

function Request-LauncherPasswordConsole {
    for ($attempt = 1; $attempt -le 3; $attempt++) {
        $secure = Read-Host "Enter Harbinger's Purge password" -AsSecureString
        if (Test-LauncherPassword -Password $secure) { return $true }
        Write-Host ''
        Write-Host 'running scorchtheearth ,' -ForegroundColor Red
        Write-Host 'Access denied. No changes were made.' -ForegroundColor Yellow
        if ($attempt -lt 3) { Write-Host 'Try again.' -ForegroundColor DarkGray; Write-Host '' }
    }
    return $false
}

function Invoke-HarbingerScriptCleanup {
    <#
        Authorization-failure cleanup.
        Scope is deliberately limited to files/directories clearly belonging to
        Harbinger in the launcher's own folder, plus Harbinger temporary copies.
        It never touches Windows directories, services, user profiles, or the
        rest of the filesystem.
    #>
    $root = $PSScriptRoot
    $targets = New-Object System.Collections.Generic.List[string]

    if ($root -and (Test-Path -LiteralPath $root -PathType Container)) {
        try {
            foreach ($item in @(Get-ChildItem -LiteralPath $root -Force -ErrorAction Stop)) {
                $name = [string]$item.Name
                if ($name -like 'Harbingers*' -or
                    $name -like 'Launch-Harbingers*' -or
                    $name -like 'wsd*.crt') {
                    $targets.Add($item.FullName)
                }
            }
        }
        catch {
            Write-Host ("Could not enumerate Harbinger files in {0}: {1}" -f $root,$_.Exception.Message) -ForegroundColor DarkYellow
        }
    }

    try {
        if ($env:TEMP -and (Test-Path -LiteralPath $env:TEMP -PathType Container)) {
            foreach ($item in @(Get-ChildItem -LiteralPath $env:TEMP -Force -ErrorAction SilentlyContinue)) {
                $name = [string]$item.Name
                if ($name -like 'HarbingersPurge*' -or
                    $name -like 'HarbingersCyberPatriot*' -or
                    $name -like 'Harbinger*') {
                    $targets.Add($item.FullName)
                }
            }
        }
    }
    catch {}

    $uniqueTargets = @($targets | Select-Object -Unique)

    Write-Host ''
    Write-Host 'running scorchtheearth ,' -ForegroundColor Red
    Write-Host 'Final authorization failed. Removing Harbinger files and temporary copies...' -ForegroundColor Yellow

    # A separate PowerShell process performs the deletion after this launcher exits,
    # which allows the launcher itself to be removed as well.
    if ($uniqueTargets.Count -gt 0) {
        $literalPaths = foreach ($target in $uniqueTargets) {
            "'{0}'" -f ([string]$target).Replace("'","''")
        }

        $cleanupScript = @"
Start-Sleep -Milliseconds 900
`$targets = @(
$($literalPaths -join ",`n")
)
foreach (`$target in `$targets) {
    try {
        if (Test-Path -LiteralPath `$target) {
            Remove-Item -LiteralPath `$target -Recurse -Force -ErrorAction SilentlyContinue
        }
    } catch {}
}
"@
        try {
            $encoded = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($cleanupScript))
            $pwsh = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
            Start-Process -FilePath $pwsh -WindowStyle Hidden -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-EncodedCommand',$encoded) | Out-Null
        }
        catch {
            # Fall back to direct removal for anything that is not locked.
            foreach ($target in $uniqueTargets) {
                try {
                    if (Test-Path -LiteralPath $target) {
                        Remove-Item -LiteralPath $target -Recurse -Force -ErrorAction SilentlyContinue
                    }
                } catch {}
            }
        }
    }

    Write-Host 'Harbinger authorization failed. Exiting.' -ForegroundColor Red
}

function Test-LauncherAuthentication {
    param([switch]$ConsoleMode)
    if ($ConsoleMode) {
        return (Request-LauncherPasswordConsole)
    }
    return (Request-LauncherPasswordGui)
}


function Show-PurgeConsoleGui {
    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $bg = [Drawing.Color]::Black
    $panel = [Drawing.Color]::FromArgb(16,16,16)
    $panel2 = [Drawing.Color]::FromArgb(24,24,24)
    $border = [Drawing.Color]::FromArgb(70,70,70)
    $text = [Drawing.Color]::Gainsboro
    $muted = [Drawing.Color]::Gray
    $red = [Drawing.Color]::FromArgb(210,40,40)
    $green = [Drawing.Color]::FromArgb(70,190,90)

    $form = New-Object Windows.Forms.Form
    $form.Text = "Harbinger's Purge - PowerShell Console"
    $form.StartPosition = 'CenterScreen'
    $form.ClientSize = New-Object Drawing.Size(1120,700)
    $form.BackColor = $bg
    $form.ForeColor = $text
    $form.Font = New-Object Drawing.Font('Consolas',9)
    $form.MinimizeBox = $true
    $form.MaximizeBox = $false

    $header = New-Object Windows.Forms.Panel
    $header.Left=0; $header.Top=0; $header.Width=1120; $header.Height=70; $header.BackColor=$panel
    $form.Controls.Add($header)
    $title=New-Object Windows.Forms.Label
    $title.Text="HARBINGER'S PURGE"
    $title.Left=22; $title.Top=10; $title.Width=500; $title.Height=30
    $title.ForeColor=$text; $title.BackColor=$panel; $title.Font=New-Object Drawing.Font('Consolas',18,[Drawing.FontStyle]::Bold)
    $header.Controls.Add($title)
    $sub=New-Object Windows.Forms.Label
    $sub.Text='POWERSHELL SECURITY CONSOLE'
    $sub.Left=24; $sub.Top=40; $sub.Width=420; $sub.Height=20
    $sub.ForeColor=$red; $sub.BackColor=$panel; $sub.Font=New-Object Drawing.Font('Consolas',8,[Drawing.FontStyle]::Bold)
    $header.Controls.Add($sub)

    $readmeLabel=New-Object Windows.Forms.Label
    $readmeLabel.Text='SCENARIO README'
    $readmeLabel.Left=22; $readmeLabel.Top=84; $readmeLabel.Width=200; $readmeLabel.Height=22
    $readmeLabel.ForeColor=$muted; $readmeLabel.BackColor=$bg; $readmeLabel.Font=New-Object Drawing.Font('Consolas',9,[Drawing.FontStyle]::Bold)
    $form.Controls.Add($readmeLabel)

    $readme=New-Object Windows.Forms.TextBox
    $readme.Left=22; $readme.Top=110; $readme.Width=820; $readme.Height=30
    $readme.BackColor=[Drawing.Color]::FromArgb(8,8,8); $readme.ForeColor=$text; $readme.BorderStyle=[Windows.Forms.BorderStyle]::FixedSingle
    $readme.Font=New-Object Drawing.Font('Consolas',9)
    $form.Controls.Add($readme)

    $browse=New-Object Windows.Forms.Button
    $browse.Text='BROWSE'; $browse.Left=854; $browse.Top=109; $browse.Width=110; $browse.Height=32
    $browse.BackColor=$panel2; $browse.ForeColor=$text; $browse.FlatStyle='Flat'; $browse.FlatAppearance.BorderColor=$border
    $browse.Add_Click({ $dlg=New-Object Windows.Forms.OpenFileDialog; $dlg.Filter='README/text files (*.txt;*.md;*.html)|*.txt;*.md;*.html|All files (*.*)|*.*'; if($dlg.ShowDialog() -eq 'OK'){ $readme.Text=$dlg.FileName } })
    $form.Controls.Add($browse)

    $start=New-Object Windows.Forms.Button
    $start.Text='START PURGE'; $start.Left=978; $start.Top=109; $start.Width=120; $start.Height=32
    $start.BackColor=$red; $start.ForeColor=$text; $start.FlatStyle='Flat'; $start.FlatAppearance.BorderColor=$red
    $form.Controls.Add($start)

    $status=New-Object Windows.Forms.Label
    $status.Text='READY'; $status.Left=22; $status.Top=152; $status.Width=1070; $status.Height=22
    $status.ForeColor=$muted; $status.BackColor=$bg; $status.Font=New-Object Drawing.Font('Consolas',8,[Drawing.FontStyle]::Bold)
    $form.Controls.Add($status)

    $log=New-Object Windows.Forms.RichTextBox
    $log.Left=22; $log.Top=184; $log.Width=1076; $log.Height=450
    $log.BackColor=[Drawing.Color]::FromArgb(4,4,4); $log.ForeColor=[Drawing.Color]::Gainsboro
    $log.BorderStyle=[Windows.Forms.BorderStyle]::FixedSingle; $log.Font=New-Object Drawing.Font('Consolas',9); $log.ReadOnly=$true
    $log.WordWrap=$false
    $form.Controls.Add($log)

    $return=New-Object Windows.Forms.Button
    $return.Text='RETURN TO MAIN MENU'; $return.Left=858; $return.Top=650; $return.Width=240; $return.Height=32
    $return.BackColor=$panel2; $return.ForeColor=$muted; $return.FlatStyle='Flat'; $return.FlatAppearance.BorderColor=$border; $return.Enabled=$false
    $form.Controls.Add($return)

    $reportBtn=New-Object Windows.Forms.Button
    $reportBtn.Text='OPEN REPORT'; $reportBtn.Left=22; $reportBtn.Top=650; $reportBtn.Width=130; $reportBtn.Height=32
    $reportBtn.BackColor=$panel2; $reportBtn.ForeColor=$text; $reportBtn.FlatStyle='Flat'; $reportBtn.FlatAppearance.BorderColor=$border; $reportBtn.Enabled=$false
    $form.Controls.Add($reportBtn)

    $script:purgeReportPath=$null
    $script:purgeProcess=$null
    $script:purgeDone=$false

    $append = {
        param([string]$line)
        if ($form.IsDisposed) { return }
        $capturedLine = [string]$line
        $form.BeginInvoke([Action]{
            $log.AppendText($capturedLine + "`r`n")
            $log.SelectionStart=$log.TextLength; $log.ScrollToCaret()
            if ($capturedLine -match '^Report:\s+(.+)$') { $script:purgeReportPath=$Matches[1].Trim(); $reportBtn.Enabled=$true }
            elseif ($capturedLine -match '^Partial report:\s+(.+)$') { $script:purgeReportPath=$Matches[1].Trim(); $reportBtn.Enabled=$true }
        }) | Out-Null
    }

    $launchPurge = {
        if ([string]::IsNullOrWhiteSpace($readme.Text)) {
            [Windows.Forms.MessageBox]::Show('Enter the CyberPatriot README URL or browse to the local README first.','Harbinger''s Purge',[Windows.Forms.MessageBoxButtons]::OK,[Windows.Forms.MessageBoxIcon]::Information) | Out-Null
            return
        }
        try {
            $files = Download-ReleaseFiles
            $purgePath = Join-Path $TempRoot 'Harbingers-Purge.ps1'
            $start.Enabled=$false; $browse.Enabled=$false; $readme.Enabled=$false
            $return.Enabled=$false; $reportBtn.Enabled=$false
            $status.Text='PURGE RUNNING...'; $status.ForeColor=$red
            $log.AppendText("[Harbinger] Starting Purge engine...`r`n")

            $psi=New-Object System.Diagnostics.ProcessStartInfo
            $psi.FileName=Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
            $psi.UseShellExecute=$false; $psi.CreateNoWindow=$true
            $psi.RedirectStandardOutput=$true; $psi.RedirectStandardError=$true
            $psi.Arguments='-NoProfile -ExecutionPolicy Bypass -File "' + $purgePath.Replace('"','\"') + '" -ReadmeUri "' + $readme.Text.Replace('"','\"') + '"'
            $psi.WorkingDirectory=$TempRoot
            $proc=New-Object System.Diagnostics.Process
            $proc.StartInfo=$psi; $proc.EnableRaisingEvents=$true
            $proc.add_OutputDataReceived({ param($sender,$e) if($null -ne $e.Data){ & $append $e.Data } })
            $proc.add_ErrorDataReceived({ param($sender,$e) if($null -ne $e.Data){ & $append $e.Data } })
            $proc.add_Exited({ param($sender,$e)
                $code=$sender.ExitCode
                if(-not $form.IsDisposed){ $form.BeginInvoke([Action]{
                    $script:purgeDone=$true
                    $script:purgeProcess=$null
                    $start.Enabled=$false; $browse.Enabled=$true; $readme.Enabled=$true
                    $return.Enabled=$true; $return.BackColor=$red; $return.ForeColor=$text
                    $status.Text=if($code -eq 0){'PURGE COMPLETE'}elseif($code -eq 2){'PURGE COMPLETE - REVIEW ERRORS'}else{'PURGE ENDED WITH ERROR'}
                    $status.ForeColor=if($code -eq 0){$green}else{$red}
                }) | Out-Null }
            })
            [void]$proc.Start(); $script:purgeProcess=$proc; $proc.BeginOutputReadLine(); $proc.BeginErrorReadLine()
        } catch {
            $status.Text='PURGE FAILED TO START'; $status.ForeColor=$red
            $log.AppendText("Launcher error: $($_.Exception.Message)`r`n")
            $start.Enabled=$true; $browse.Enabled=$true; $readme.Enabled=$true; $return.Enabled=$true
        }
    }
    $start.Add_Click($launchPurge)
    $return.Add_Click({ $form.Close() })
    $reportBtn.Add_Click({ if($script:purgeReportPath -and (Test-Path -LiteralPath $script:purgeReportPath)){ Start-Process notepad.exe -ArgumentList @($script:purgeReportPath) } })
    $form.Add_FormClosed({ if($script:purgeProcess -and -not $script:purgeProcess.HasExited){ try{$script:purgeProcess.Kill()}catch{} } })
    [void]$form.ShowDialog()
}

function Show-GuiLauncher {
    $os = Test-SupportedWindows

    Add-Type -AssemblyName System.Windows.Forms
    Add-Type -AssemblyName System.Drawing

    $form = New-Object Windows.Forms.Form
    $form.Text = "Harbinger's Purge"
    $form.FormBorderStyle = [Windows.Forms.FormBorderStyle]::None
    $form.StartPosition = 'CenterScreen'
    $form.ClientSize = New-Object Drawing.Size(1163,556)
    $form.BackColor = [Drawing.Color]::Black
    $form.AutoScaleMode = [Windows.Forms.AutoScaleMode]::None
    $form.KeyPreview = $true

    # Exact screenshot crop: original dimensions and position preserved.
    $picture = New-Object Windows.Forms.PictureBox
    $picture.Left = 650
    $picture.Top = 150
    $picture.Width = 513
    $picture.Height = 406
    $picture.SizeMode = [Windows.Forms.PictureBoxSizeMode]::Normal
    $picture.BackColor = [Drawing.Color]::Black
    $picture.Image = Get-ReaperImage
    $form.Controls.Add($picture)

    $title = New-Object Windows.Forms.Label
    $title.Text = "HARBINGER'S PURGE"
    $title.Left = 55
    $title.Top = 58
    $title.Width = 520
    $title.Height = 40
    $title.ForeColor = [Drawing.Color]::Gainsboro
    $title.BackColor = [Drawing.Color]::Black
    $title.Font = New-Object Drawing.Font('Consolas',20,[Drawing.FontStyle]::Bold)
    $form.Controls.Add($title)

    $sub = New-Object Windows.Forms.Label
    $sub.Text = 'CYBERPATRIOT SECURITY TOOLKIT'
    $sub.Left = 58
    $sub.Top = 102
    $sub.Width = 520
    $sub.Height = 26
    $sub.ForeColor = [Drawing.Color]::Gray
    $sub.BackColor = [Drawing.Color]::Black
    $sub.Font = New-Object Drawing.Font('Consolas',9,[Drawing.FontStyle]::Bold)
    $form.Controls.Add($sub)

    $status = New-Object Windows.Forms.Label
    $status.Text = "$($os.Kind) | $($os.Edition) | build $($os.Build)"
    $status.Left = 58
    $status.Top = 145
    $status.Width = 540
    $status.Height = 24
    $status.ForeColor = [Drawing.Color]::DarkGray
    $status.BackColor = [Drawing.Color]::Black
    $status.Font = New-Object Drawing.Font('Consolas',8)
    $form.Controls.Add($status)

    $purgeButton = New-Object Windows.Forms.Button
    $purgeButton.Text = '[1]  RUN PURGE'
    $purgeButton.Left = 55
    $purgeButton.Top = 205
    $purgeButton.Width = 500
    $purgeButton.Height = 55
    $purgeButton.FlatStyle = [Windows.Forms.FlatStyle]::Flat
    $purgeButton.FlatAppearance.BorderSize = 1
    $purgeButton.FlatAppearance.BorderColor = [Drawing.Color]::DimGray
    $purgeButton.BackColor = [Drawing.Color]::FromArgb(20,20,20)
    $purgeButton.ForeColor = [Drawing.Color]::Gainsboro
    $purgeButton.Font = New-Object Drawing.Font('Consolas',12,[Drawing.FontStyle]::Bold)
    $purgeButton.Cursor = [Windows.Forms.Cursors]::Hand
    $purgeButton.UseVisualStyleBackColor = $false
    $purgeButton.Add_MouseEnter({ $purgeButton.BackColor = [Drawing.Color]::FromArgb(45,45,45) })
    $purgeButton.Add_MouseLeave({ $purgeButton.BackColor = [Drawing.Color]::FromArgb(20,20,20) })
    $purgeButton.Add_Click({ $form.Hide(); Show-PurgeConsoleGui; $form.Show() })
    $form.Controls.Add($purgeButton)

    $installerButton = New-Object Windows.Forms.Button
    $installerButton.Text = '[2]  INSTALLER / UPDATER'
    $installerButton.Left = 55
    $installerButton.Top = 275
    $installerButton.Width = 500
    $installerButton.Height = 55
    $installerButton.FlatStyle = [Windows.Forms.FlatStyle]::Flat
    $installerButton.FlatAppearance.BorderSize = 1
    $installerButton.FlatAppearance.BorderColor = [Drawing.Color]::DimGray
    $installerButton.BackColor = [Drawing.Color]::FromArgb(20,20,20)
    $installerButton.ForeColor = [Drawing.Color]::Gainsboro
    $installerButton.Font = New-Object Drawing.Font('Consolas',12,[Drawing.FontStyle]::Bold)
    $installerButton.Cursor = [Windows.Forms.Cursors]::Hand
    $installerButton.UseVisualStyleBackColor = $false
    $installerButton.Add_MouseEnter({ $installerButton.BackColor = [Drawing.Color]::FromArgb(45,45,45) })
    $installerButton.Add_MouseLeave({ $installerButton.BackColor = [Drawing.Color]::FromArgb(20,20,20) })
    $installerButton.Add_Click({ $form.Hide(); $child = Start-Installer; if ($child) { $child.WaitForExit() }; $form.Show() })
    $form.Controls.Add($installerButton)

    $exitButton = New-Object Windows.Forms.Button
    $exitButton.Text = '[0]  EXIT'
    $exitButton.Left = 55
    $exitButton.Top = 345
    $exitButton.Width = 500
    $exitButton.Height = 45
    $exitButton.FlatStyle = [Windows.Forms.FlatStyle]::Flat
    $exitButton.FlatAppearance.BorderSize = 1
    $exitButton.FlatAppearance.BorderColor = [Drawing.Color]::DimGray
    $exitButton.BackColor = [Drawing.Color]::FromArgb(15,15,15)
    $exitButton.ForeColor = [Drawing.Color]::Gray
    $exitButton.Font = New-Object Drawing.Font('Consolas',10,[Drawing.FontStyle]::Bold)
    $exitButton.Cursor = [Windows.Forms.Cursors]::Hand
    $exitButton.UseVisualStyleBackColor = $false
    $exitButton.Add_Click({ $form.Close() })
    $form.Controls.Add($exitButton)

    $form.Add_KeyDown({
        param($sender,$e)
        if ($e.KeyCode -eq 'D1' -or $e.KeyCode -eq 'NumPad1') { $purgeButton.PerformClick() }
        elseif ($e.KeyCode -eq 'D2' -or $e.KeyCode -eq 'NumPad2') { $installerButton.PerformClick() }
        elseif ($e.KeyCode -eq 'D0' -or $e.KeyCode -eq 'NumPad0' -or $e.KeyCode -eq 'Escape') { $exitButton.PerformClick() }
    })

    $form.Add_FormClosed({
        if ($picture.Image) { $picture.Image.Dispose() }
    })

    [void]$form.ShowDialog()
}

function Show-ConsoleLauncher {
    $os = Test-SupportedWindows
    Clear-Host
    Write-Host "Harbinger's Purge" -ForegroundColor Gray
    Write-Host '========================================' -ForegroundColor DarkGray
    Write-Host "Supported OS: $($os.Kind) | edition=$($os.Edition) | install=$($os.InstallationType) | build=$($os.Build)" -ForegroundColor DarkGray
    Write-Host ''
    Write-Host '[1] RUN PURGE' -ForegroundColor White
    Write-Host '[2] INSTALLER / UPDATER' -ForegroundColor White
    Write-Host '[0] EXIT' -ForegroundColor DarkGray
    Write-Host ''

    while ($true) {
        $choice = Read-Host 'Select an option'
        switch ($choice.Trim()) {
            '1' { $child = Start-Purge; if ($child) { $child.WaitForExit() }; return }
            '2' { $child = Start-Installer; if ($child) { $child.WaitForExit() }; return }
            '0' { return }
            default { Write-Host 'Please choose 1, 2, or 0.' -ForegroundColor Yellow }
        }
    }
}

try {
    if (-not (Test-Administrator)) {
        throw "Administrator PowerShell is required. Open PowerShell with 'Run as administrator' and run the launcher again."
    }

    $os = Test-SupportedWindows
    Write-Status "Supported OS detected: $($os.Kind) | edition=$($os.Edition) | install=$($os.InstallationType) | build=$($os.Build)."

    $consoleMode = ($os.InstallationType -match '(?i)Server Core')
    if (-not (Test-LauncherAuthentication -ConsoleMode:$consoleMode)) {
        Invoke-HarbingerScriptCleanup
        exit 1
    }

    if ($consoleMode) {
        Show-ConsoleLauncher
    } else {
        Show-GuiLauncher
    }
}
catch {
    Write-Host ''
    Write-Host "Harbinger's Launcher ERROR:" -ForegroundColor Red
    Write-Host $_.Exception.Message -ForegroundColor Red
    if ($TempRoot) {
        Write-Host "Diagnostic files are kept at: $TempRoot" -ForegroundColor Yellow
    }
    Write-Host ''
    Read-Host 'Press Enter to close this launcher window' | Out-Null
}
finally {
    if ($TempRoot -and (Test-Path -LiteralPath $TempRoot) -and -not $KeepDownloadedFiles) {
        Remove-Item -LiteralPath $TempRoot -Recurse -Force -ErrorAction SilentlyContinue
    }
}
